// Parallel Bible corpus (Bibel Simalungun 2007 ↔ Alkitab Terjemahan Baru) and the
// statistical word lexicon learned from it. Generated by scripts/build-bible-corpus.mjs
// into public/data/ and loaded lazily, so it works on static hosts like GitHub Pages.

/** [bookIndex, chapter, verse, simalungun, indonesian] */
export type ParallelVerse = [number, number, number, string, string];
/** [word, verseFrequency, [[indonesian, score], ...], exampleVerseIndexes] */
export type LexiconRow = [string, number, [string, number][], number[]];

export interface BibleCorpus {
  source: string;
  /** [code, simalungunName, indonesianName] */
  books: [string, string, string][];
  verses: ParallelVerse[];
  lexicon: LexiconRow[];
  bySmgWord: Map<string, LexiconRow>;
  /** indonesian word -> simalungun rows whose candidates include it, best first */
  byIdnWord: Map<string, { row: LexiconRow; score: number }[]>;
}

export interface WordLookup {
  query: string;
  matchedWord: string;
  frequency: number;
  candidates: { indonesian: string; score: number }[];
  examples: ParallelVerse[];
  confidence: 'tinggi' | 'sedang' | 'rendah';
}

let loading: Promise<BibleCorpus> | null = null;
let loaded: BibleCorpus | null = null;

/** The corpus if it has finished loading, for synchronous callers like the offline translator. */
export function getLoadedBibleCorpus(): BibleCorpus | null {
  return loaded;
}

export function loadBibleCorpus(): Promise<BibleCorpus> {
  if (!loading) {
    loading = Promise.all([
      fetch('data/bible-parallel.json').then((r) => r.json()),
      fetch('data/smg-lexicon.json').then((r) => r.json()),
    ])
      .then(([bible, lex]) => (loaded = buildIndexes(bible, lex.lexicon)))
      .catch((err) => {
        loading = null; // allow retry
        throw err;
      });
  }
  return loading;
}

function buildIndexes(
  bible: { source: string; books: [string, string, string][]; verses: ParallelVerse[] },
  lexicon: LexiconRow[]
): BibleCorpus {
  const bySmgWord = new Map<string, LexiconRow>();
  const byIdnWord = new Map<string, { row: LexiconRow; score: number }[]>();
  for (const row of lexicon) {
    bySmgWord.set(row[0], row);
    for (const [idn, score] of row[2]) {
      // weight by frequency so common words win over rare ones with similar scores
      const weighted = score * Math.log2(row[1] + 1);
      const list = byIdnWord.get(idn) || [];
      list.push({ row, score: weighted });
      byIdnWord.set(idn, list);
    }
  }
  for (const list of byIdnWord.values()) list.sort((a, b) => b.score - a.score);
  return { ...bible, lexicon, bySmgWord, byIdnWord };
}

export function verseReference(corpus: BibleCorpus, v: ParallelVerse): string {
  const [, smgName, idnName] = corpus.books[v[0]];
  const cv = `${v[1]}:${v[2]}`;
  return smgName.toLowerCase() === idnName.toLowerCase()
    ? `${idnName} ${cv}`
    : `${idnName} ${cv} (${smgName} ${cv})`;
}

function confidenceOf(freq: number, topScore: number): WordLookup['confidence'] {
  if (freq >= 10 && topScore >= 0.4) return 'tinggi';
  if (freq >= 3 && topScore >= 0.15) return 'sedang';
  return 'rendah';
}

const normalizeWord = (w: string) =>
  w
    .toLowerCase()
    .replace(/[^a-zà-ÿ-]/g, '')
    .replace(/^-+|-+$/g, '');

// Simalungun possessive suffixes: tanohni, uhurmu, bapanami, ...
const SMG_SUFFIXES = ['nasiam', 'nima', 'nami', 'nasida', 'ni', 'mu', 'hu', 'ta', 'kon'];

/** Simalungun word → Indonesian meanings learned from the parallel Bible. */
export function lookupSimalungunWord(corpus: BibleCorpus, rawWord: string): WordLookup | null {
  const word = normalizeWord(rawWord);
  if (!word) return null;
  let row = corpus.bySmgWord.get(word);
  if (!row) {
    for (const suffix of SMG_SUFFIXES) {
      if (word.length > suffix.length + 2 && word.endsWith(suffix)) {
        row = corpus.bySmgWord.get(word.slice(0, -suffix.length));
        if (row) break;
      }
    }
  }
  if (!row) return null;
  const candidates = row[2].map(([indonesian, score]) => ({ indonesian, score }));
  return {
    query: rawWord,
    matchedWord: row[0],
    frequency: row[1],
    candidates,
    examples: row[3].map((i) => corpus.verses[i]),
    confidence: confidenceOf(row[1], candidates[0]?.score ?? 0),
  };
}

const IDN_SUFFIXES = ['lah', 'kah', 'nya', 'mu', 'ku'];

/** Indonesian word → Simalungun words that translate to it. */
export function lookupIndonesianWord(
  corpus: BibleCorpus,
  rawWord: string,
  max = 5
): { simalungun: string; frequency: number; score: number }[] {
  const word = normalizeWord(rawWord);
  let list = corpus.byIdnWord.get(word);
  if (!list) {
    for (const suffix of IDN_SUFFIXES) {
      if (word.length > suffix.length + 2 && word.endsWith(suffix)) {
        list = corpus.byIdnWord.get(word.slice(0, -suffix.length));
        if (list) break;
      }
    }
  }
  return (list || []).slice(0, max).map(({ row, score }) => ({
    simalungun: row[0],
    frequency: row[1],
    score,
  }));
}

/** Finds a verse by reference in either language: "Yohanes 3:16", "1 Musa 1:1", "mazmur 23 1". */
export function findVerseByReference(corpus: BibleCorpus, query: string): ParallelVerse[] | null {
  const m = query
    .trim()
    .toLowerCase()
    .match(/^(\d?\s?[a-z][a-z\s-]*?)\s*(\d+)(?:\s*[:.,\s]\s*(\d+)(?:\s*[-–]\s*(\d+))?)?$/);
  if (!m) return null;
  const name = m[1].replace(/\s+/g, ' ').trim();
  const compact = name.replace(/\s/g, '');
  const bookIndex = corpus.books.findIndex(([code, smg, idn]) =>
    [smg, idn, code].some((n) => {
      const ln = n.toLowerCase();
      return ln === name || ln.replace(/\s/g, '') === compact || (compact.length >= 3 && ln.replace(/\s/g, '').startsWith(compact));
    })
  );
  if (bookIndex < 0) return null;
  const chapter = Number(m[2]);
  const from = m[3] ? Number(m[3]) : 1;
  const to = m[4] ? Number(m[4]) : m[3] ? from : 999;
  const hits = corpus.verses.filter(
    (v) => v[0] === bookIndex && v[1] === chapter && v[2] >= from && v[2] <= to
  );
  return hits.length ? hits : null;
}

/** Full-text search over both languages. Whole-word matches rank first, short verses next. */
export function searchVerses(corpus: BibleCorpus, query: string, limit = 20): ParallelVerse[] {
  const byRef = findVerseByReference(corpus, query);
  if (byRef) return byRef.slice(0, limit);
  const q = query.trim().toLowerCase();
  if (q.length < 2) return [];
  const escaped = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const wholeWord = new RegExp(`(^|[^a-zà-ÿ])${escaped}($|[^a-zà-ÿ])`, 'i');
  const hits: { v: ParallelVerse; rank: number }[] = [];
  for (const v of corpus.verses) {
    const smg = v[3].toLowerCase();
    const idn = v[4].toLowerCase();
    if (!smg.includes(q) && !idn.includes(q)) continue;
    const whole = wholeWord.test(smg) || wholeWord.test(idn);
    hits.push({ v, rank: (whole ? 0 : 10000) + v[3].length });
  }
  return hits
    .sort((a, b) => a.rank - b.rank)
    .slice(0, limit)
    .map((h) => h.v);
}

/** Total number of verses containing the query (for "n ayat ditemukan"). */
export function countVerses(corpus: BibleCorpus, query: string): number {
  const q = query.trim().toLowerCase();
  if (q.length < 2) return 0;
  let n = 0;
  for (const v of corpus.verses) if (v[3].toLowerCase().includes(q) || v[4].toLowerCase().includes(q)) n++;
  return n;
}
